import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Prepare collaboration and team access","description":"","frontmatter":{"title":"Prepare collaboration and team access","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"en","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"05f448dda78b05027b84b2c03f08a15eb515aee05af79397a1596d7e40ec5d40","translationRevision":"05f448dda78b05027b84b2c03f08a15eb515aee05af79397a1596d7e40ec5d40","order":30},"headers":[],"relativePath":"en/user/cloud/collaboration.md","filePath":"en/user/cloud/collaboration.md","lastUpdated":1795727787000}`),a={name:`en/user/cloud/collaboration.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="prepare-collaboration-and-team-access" tabindex="-1">Prepare collaboration and team access <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to “Prepare collaboration and team access”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Grant another operator a defined role while retaining owner control. Remote access is provided by the installable <strong>Remote Control</strong> plugin, not by a Settings tab: you need <a href="./account.html">Cloud sign-in</a>, a matching backend and the plugin installed for this host. Start with read-only access and a nonproduction setup.</p><h2 id="configure-remote-access" tabindex="-1">Configure remote access <a class="header-anchor" href="#configure-remote-access" aria-label="Permalink to “Configure remote access”">​</a></h2><ol><li>Install and enable <code>tiktools.remote-control</code>, then open its <strong>Remote control</strong> page.</li><li>Create a team and enroll <strong>this PC</strong> as its host with a recognizable device label; start the relay link and wait for its status to reach <code>ready</code>.</li><li>Create an invitation and deliver its one-time token through a trusted channel. An invitation is not an approved active session.</li><li>Review the incoming request and requested role. Approve only the expected operator; the grant stays <code>pendingHost</code> until the host link confirms it.</li><li>Inspect grants and devices regularly. Revoke a grant when its access is no longer needed.</li></ol><p>Delegated definition editing, adopting a definition as owner and approving delegated execution are distinct decisions. Read the saved source, referenced actions and permissions in the specific review. A definition preview alone does not authorize an effect.</p><h2 id="prepare-a-controller-device" tabindex="-1">Prepare a controller device <a class="header-anchor" href="#prepare-a-controller-device" aria-label="Permalink to “Prepare a controller device”">​</a></h2><p>On the controlling device, sign in with its own account, enroll it as a controller and redeem the invitation token. A pending request then appears for the owner. Nickname lookup needs a separately deployed backend endpoint and may be unavailable on the current service. Do not assume a failed lookup means the person has no account, and do not substitute an arbitrary ID to bypass selection.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Expected result and status”">​</a></h2><p>The two-account flow (team, host link, invitation, approval, read command, revoke) has been verified against a local backend. The Settings collaboration/team tabs were removed; the native collaboration service has no web UI in this build. Production relay/NAT behavior, nickname lookup and two-PC LIVE operation are not established here. A ready link alone does not prove end-to-end permission enforcement for your intended action.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recovery”">​</a></h2><p>For stale grants, revoke access and review it again after the host link refreshes. For unconfirmed commands, inspect the recorded outcome before retrying. Stop the relay link or revoke access when ending a session. Keep invitation tokens and credentials out of public <a href="./../preferences/troubleshooting.html">diagnostic reports</a>.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Operational details”">​</a></h2><p>Every remote command crosses the host&#39;s capability gate (<code>remote.command.dispatch</code>, <code>remote.pair.list</code>, <code>remote.grant.list</code>, <code>remote.grant.revoke</code>, <code>remote.controller.ticket</code>); the plugin never receives a Control API or a full bearer token. An active transport or team membership alone grants no native access. Observer is read-oriented; moderator adds selected operational controls, automationEditor adds selected editing, and custom requires an explicit reviewed policy. None grants unrestricted scripts or external effects. See <a href="./../../developer/collaboration.html#operational-details">the role and confirmation contract</a> and <a href="./../../developer/transports.html">transports</a> for the current boundary.</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};